import {proofIsCurrent,diagnose} from './operations.mjs';
export function queueFor(s){if(proofIsCurrent(s))return 'resolved';if(s.phase==='verified')return 'attention';if(['investigated','rehearsed','approved','unverified','verifying','verify-only','blocked','needs-evidence','stale'].includes(s.phase))return 'attention';return 'investigating';}
export function nextStep(s){if(s.phase==='verified'&&!proofIsCurrent(s))return ['verify','Recheck changed evidence'];if(s.job?.pending)return ['refresh','Refresh workflow status'];return ({paid:['investigate','Review purchase evidence'],unpaid:['pay','Create sample payment'],reviewing:['investigate','Retry investigation'],investigated:['rehearse','Preview correction'],rehearsed:['approve','Approve this access grant'],approved:['repair','Apply & verify access'],unverified:['verify','Retry verification only'],verifying:['verify','Check verification'], 'verify-only':['verify','Verify existing access'],stale:['investigate','Review changed evidence'],'needs-evidence':['investigate','Check evidence again'],blocked:['investigate','Recheck evidence'],verified:['receipt','Download recovery receipt']})[s.phase]||['investigate','Review evidence'];}
export function caseLabel(s){if(proofIsCurrent(s))return 'Access verified';if(s.phase==='approved')return 'Approved · ready to apply';if(s.phase==='rehearsed')return 'Preview ready for approval';if(['unverified','verifying'].includes(s.phase))return 'Access updated · verification needed';if(s.phase==='investigated')return 'Ready to preview';return diagnose(s).title;}
